/* Chunk Reading Studio — no frameworks / no CDN / local-only learning state. */
(() => {
'use strict';
const root=document.getElementById('app');
const authHash='09090c74379eedfd5cb1abf8fbcf40f0933937fd4e1a9d5f63982f43a18f304f';
const STORE='chunk-reading-studio-v1';const LOGIN='chunk-reading-studio-login';const REMEMBER='chunk-reading-studio-remember';
const defaultSettings={theme:'light',font:19,line:1.86,translation:true,speed:0.9,voice:'',dailyTarget:3};
const readStore=()=>{try {const a=JSON.parse(localStorage.getItem(STORE)||'{}');return a&&typeof a==='object'?a:{}}catch{return {}}};
const state=Object.assign({settings:{},progress:{},saved:{},known:{},notes:{},quizHistory:{},daily:{},recent:'',favorites:{},wordKnown:{}},readStore());
state.settings=Object.assign({},defaultSettings,state.settings||{});
for(const name of ['progress','saved','known','notes','quizHistory','daily','favorites','wordKnown'])if(!state[name]||typeof state[name]!=='object')state[name]={};
const save=()=>{try{localStorage.setItem(STORE,JSON.stringify(state));}catch{toast('저장 공간이 부족합니다. 진도 백업 후 저장 공간을 정리해 주세요.')}};
let lessons=[],byId={},loaded=false,route={page:'home'},libraryFilter='all',libraryQuery='',libraryOrder='sequence',focus=false,focusIndex=0,quiz=null,flipIndex=0,flipped=false,ttsVoices=[],audioQueue=[],audioPos=0,paused=false,timerStart=0,timerTicker=0,toastTimer=0;
const $=s=>document.querySelector(s);const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const e=escapeHtml;
const attr=s=>e(s).replace(/`/g,'&#96;');
const button=(label,action,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-act="${action}" ${extra}>${label}</button>`;
const empty=(title,text)=>`<div class="empty"><div style="font-size:32px">◇</div><strong>${e(title)}</strong>${e(text)}</div>`;
const fmt=n=>Number(n||0).toLocaleString('ko-KR');
const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const getLesson=(id)=>byId[id]||lessons[0];
const getProgress=(id)=>state.progress[id]||{};
const done=id=>!!getProgress(id).completed;
const completed=arr=>arr.filter(x=>done(x.id)).length;
const labels={home:'홈',library:'전체 학습',lesson:'학습실',review:'복습',stats:'성장 기록',settings:'설정',guide:'학습 안내'};
const level=l=>l.track==='university'?'C1 대학·학술':l.number<=10?'B1 기초':l.number<=20?'B1+–B2 중급':'B2 심화';
const pair=l=>l.track==='core'?`U${String(l.number).padStart(2,'0')}`:String(l.number).padStart(2,'0');
const strip=s=>String(s||'').replace(/\*\*/g,'').replace(/\*/g,'').replace(/`/g,'').replace(/\[(.*?)\]\([^)]*\)/g,'$1').replace(/<[^>]+>/g,'').trim();
function toast(s){let el=$('.toast');if(!el){el=document.createElement('div');el.className='toast';el.setAttribute('role','status');document.body.appendChild(el)}el.textContent=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3000);const live=$('#live-status');if(live)live.textContent=s;}
function applySettings(){document.documentElement.dataset.theme=state.settings.theme==='dark'?'dark':'light';document.documentElement.style.setProperty('--font-reader',`${Number(state.settings.font)||19}px`);document.documentElement.style.setProperty('--line-reader',`${Number(state.settings.line)||1.86}`);}
function logo(){return `<div class="brand"><div class="brand-mark">◧</div><div><div class="brand-name">Chunk Reading Studio</div><div class="brand-sub">READ · UNDERSTAND · SPEAK</div></div></div>`;}
function readAuth(){if(sessionStorage.getItem(LOGIN)==='1')return true;try{return Number(localStorage.getItem(REMEMBER))>Date.now()}catch{return false}}
async function checkPassword(value){if(crypto?.subtle){const ab=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));const hex=[...new Uint8Array(ab)].map(x=>x.toString(16).padStart(2,'0')).join('');return hex===authHash;} // no WebCrypto: small compatibility fallback for local file browsers
return smallHash(value)==='dca7b0f5';}
function smallHash(str){let h=0x811c9dc5;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,0x01000193)}return(h>>>0).toString(16).padStart(8,'0');}
function renderLogin(){applySettings();root.innerHTML=`<div class="login-screen"><section class="login-feature">${logo()}<div><div style="letter-spacing:.19em;color:#80e8d4;font-size:11px;font-weight:750">YOUR PERSONAL READING LIBRARY</div><h1>읽는 힘을<br><em>말하는 자신감</em>으로.</h1><p class="lead">영어 어순 그대로 이해하는 청크 읽기, 문장 낭독, 어휘 복습까지. 기초에서 학술 영어까지 한 곳에서 연습하세요.</p><div class="login-stats"><div><b>60</b><small>Original Essays</small></div><div><b>1,759</b><small>Sentences</small></div><div><b>B1–C1</b><small>Learning Levels</small></div></div></div><div style="color:#acd1df;font-size:12px">30 Core + 30 University · 한국어 직독직해 통합 학습</div></section><section class="login-right"><form class="login-form-box" id="login-form"><span class="pill aqua">PRIVATE STUDY SPACE</span><h2 style="margin-top:18px">다시 만나 반가워요.</h2><p class="lead">학습을 시작하려면 접근 비밀번호를 입력하세요.<br>개인 학습 기록은 이 기기에 저장됩니다.</p><label for="login-pw">접근 비밀번호</label><div class="password-wrap"><input id="login-pw" type="password" autocomplete="current-password" placeholder="비밀번호 입력" required autofocus><button type="button" class="btn" id="show-password" aria-label="비밀번호 표시" title="비밀번호 표시">◉</button></div><div id="login-error" class="login-error" aria-live="polite"></div><label class="checkline"><input id="login-remember" type="checkbox" checked> 이 브라우저에서 7일간 로그인 유지</label><button type="submit" class="btn btn-primary login-submit">학습 시작 →</button><div class="login-hint">🔒 <strong>안내:</strong> 이 기능은 화면 진입을 제한하는 간단한 장치입니다. GitHub Pages의 공개 HTML·JS·학습 데이터는 서버에서 보호되지 않으며, 기술적으로 누구나 조회할 수 있습니다. 민감한 자료는 올리지 마세요.</div></form></section></div>`;
$('#login-form').addEventListener('submit',async ev=>{ev.preventDefault();const inp=$('#login-pw'),err=$('#login-error');err.textContent='확인 중…';try{const ok=await checkPassword(inp.value);if(!ok){err.textContent='비밀번호가 올바르지 않습니다.';inp.select();return;}sessionStorage.setItem(LOGIN,'1');if($('#login-remember').checked)localStorage.setItem(REMEMBER,String(Date.now()+7*86400000));else localStorage.removeItem(REMEMBER);loadData();}catch{err.textContent='비밀번호 확인에 실패했습니다. 브라우저를 확인해 주세요.'}});
$('#show-password').addEventListener('click',()=>{const v=$('#login-pw');v.type=v.type==='password'?'text':'password';v.focus()});}
function loadData(){if(loaded){render();return;}root.innerHTML='<div class="boot">학습 콘텐츠 불러오는 중 <span class="loading-dot"></span></div>';const script=document.createElement('script');script.src='content.js';script.onload=()=>{const data=window.STUDIO_DATA;if(!data||!Array.isArray(data.lessons)){root.innerHTML=empty('데이터 오류','content.js 파일이 필요합니다. ZIP의 폴더 구조를 유지하세요.');return}lessons=data.lessons;byId=Object.fromEntries(lessons.map(x=>[x.id,x]));loaded=true;route=parseRoute();applySettings();render();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./service-worker.js').catch(()=>{});initVoices()};script.onerror=()=>{root.innerHTML=empty('콘텐츠 파일을 읽지 못했습니다','GitHub Pages에 content.js를 업로드했는지 확인하세요.');};document.body.appendChild(script)}
function parseRoute(){const path=(location.hash||'#/home').replace(/^#\/?/,'').split('/').filter(Boolean);const page=path[0]||'home';return {page:['home','library','lesson','review','stats','settings','guide'].includes(page)?page:'home',id:path[1]||state.recent||'01',mode:path[2]||'chunks'}};
function go(path){stopTTS();stopTimer(false);if(location.hash==='#/'+path){route=parseRoute();render();window.scrollTo({top:0})}else location.hash='#/'+path;}
function touchLesson(id){if(!byId[id])return;const p=state.progress[id]||{};const first=p.lastDay!==today();p.lastDay=today();p.views=(p.views||0)+(first?1:0);p.lastVisit=Date.now();state.progress[id]=p;state.recent=id;if(first)state.daily[today()]=(state.daily[today()]||0)+1;save()}
function render(){if(!loaded)return;applySettings();route=parseRoute();if(route.page==='lesson'&&!byId[route.id])route.id='01';if(route.page==='lesson'&&route.id!==state.recent)touchLesson(route.id);const r=route;let body='';switch(r.page){case 'home':body=renderHome();break;case 'library':body=renderLibrary();break;case 'lesson':body=renderLesson(getLesson(r.id),r.mode);break;case 'review':body=renderReview();break;case 'stats':body=renderStats();break;case 'settings':body=renderSettings();break;case 'guide':body=renderGuide();break;default:body=renderHome()}
root.innerHTML=`<div class="shell"><aside class="sidebar">${logo()}<div><div class="nav-label">MAIN MENU</div><div class="nav-stack">${navButton('home','⌂','대시보드')}${navButton('library','▦','60편 학습 목록')}${navButton('lesson','▤','이어 공부하기')}${navButton('review','◇','나의 복습함')}${navButton('stats','▥','학습 통계')}</div><div class="nav-label" style="margin-top:27px">PREFERENCES</div><div class="nav-stack">${navButton('settings','⚙','설정 및 백업')}${navButton('guide','ⓘ','학습 안내')}</div></div><div class="sidebar-bottom"><div class="quote">“Slow reading builds<br><b>strong understanding.</b>”<div style="margin-top:11px;opacity:.75">기초부터 학술 영어까지<br>매일 조금씩, 꾸준하게.</div></div></div></aside><div class="shell-main"><header class="topbar"><div class="topbar-label">${e(labels[r.page])}${r.page==='lesson'?' <span style="color:var(--muted)">/ '+e(getLesson(r.id).id)+'</span>':''}</div><div class="topbar-actions"><span class="pill aqua hide-mobile">● 개인 학습 공간</span>${button('◖','theme','btn-quiet','aria-label="다크 모드 전환" title="테마 전환"')}${button('ⓘ','help','btn-quiet','aria-label="단축키 도움말" title="도움말"')}${button('나가기','logout','btn-sm hide-mobile')}</div></header><main class="main-content" id="content" tabindex="-1">${body}</main></div><nav class="bottomnav" aria-label="모바일 메뉴">${bottomButton('home','⌂','홈')}${bottomButton('library','▦','목록')}${bottomButton('lesson','▤','학습')}${bottomButton('review','◇','복습')}${bottomButton('settings','⚙','설정')}</nav></div><dialog class="help-dialog" id="help-dialog"><h2 style="font-size:23px">학습 단축키 안내</h2><p class="muted" style="line-height:1.9">학습실에서 아래 키를 사용해 보세요. 텍스트를 입력하는 동안에는 동작하지 않습니다.</p><table class="detail-table"><tr><td><span class="kbd">Space</span></td><td>음성 일시정지 / 재개</td></tr><tr><td><span class="kbd">←</span> <span class="kbd">→</span></td><td>포커스 카드 이동</td></tr><tr><td><span class="kbd">T</span></td><td>한국어 뜻 표시 / 숨기기</td></tr><tr><td><span class="kbd">S</span></td><td>선택된 문장 낭독</td></tr><tr><td><span class="kbd">Esc</span></td><td>음성 정지</td></tr></table><div style="text-align:right;margin-top:20px">${button('닫기','closeHelp','btn-primary')}</div></dialog>`;
updateTimer();}
function navButton(page,icon,text){const active=route.page===page;const path=page==='lesson'?`lesson/${state.recent||'01'}/chunks`:page;return `<button type="button" class="nav-item${active?' active':''}" data-go="${path}" ${active?'aria-current="page"':''}><span class="ico">${icon}</span> ${text}</button>`}
function bottomButton(page,icon,text){const active=route.page===page;return `<button type="button" class="${active?'active':''}" data-go="${page==='lesson'?`lesson/${state.recent||'01'}/chunks`:page}" ${active?'aria-current="page"':''}><span class="ico">${icon}</span><span>${text}</span></button>`}
function lessonCard(l){const p=getProgress(l.id);const marked=p.completed;return `<article class="lesson-card surface"><div class="card-top"><span class="lesson-id">${e(l.id)} · ${l.track==='core'?'CORE':'UNIVERSITY'}</span><button type="button" class="btn btn-sm btn-quiet" title="즐겨찾기" aria-label="즐겨찾기" data-act="favorite" data-id="${l.id}">${state.favorites[l.id]?'★':'☆'}</button></div><h3>${e(l.title)}</h3><div class="kr-title">${e(l.subtitle)}</div><div class="chipbar"><span class="tag">${e(level(l))}</span><span class="tag">${fmt(l.wordCount)} 단어</span><span class="tag">${l.sentences.length} 문장</span></div><div class="card-bottom"><span class="small-meta">${marked?'✓ 완료':'↗ 낭독 학습'}</span><button class="btn btn-sm ${marked?'':'btn-primary'}" type="button" data-go="lesson/${l.id}/chunks">${marked?'다시 학습':'학습 시작'} →</button></div><div class="progress"><span style="width:${marked?'100':p.lastVisit?'35':'0'}%"></span></div></article>`}
function statCard(icon,n,label){return `<div class="surface statbox"><div class="stat-icon">${icon}</div><div><div class="stat-number">${n}</div><div class="stat-label">${label}</div></div></div>`}
function renderHome(){const core=lessons.filter(x=>x.track==='core'),uni=lessons.filter(x=>x.track==='university');const d=completed(lessons),stats=window.STUDIO_DATA.stats;const recent=getLesson(state.recent||'01');const suggestion=lessons.find(l=>!done(l.id))||lessons[0];const daily=state.daily[today()]||0;return `<div class="content-wide"><section class="hero surface"><div><div class="eyebrow" style="color:#93e8d6">YOUR LEARNING DASHBOARD</div><h1>오늘도 한 문장씩,<br>영어가 자연스러워지는 시간.</h1><p>청크로 뜻을 이해하고, 문장을 소리 내어 읽고, 원문을 유창하게 낭독해 보세요. 학습 진도는 자동으로 이 브라우저에 저장됩니다.</p><div class="flex flex-wrap">${button('이어서 학습 →',`goRecent`,'')}${button('전체 60편 보기','goLibrary','btn-quiet','style="color:#fff;background:transparent;border-color:#ffffff70"')}</div></div><div class="hero-illus" aria-hidden="true">◧</div></section><div class="grid-cols-3 mt16">${statCard('▦',`${d} / 60`,'완료한 에세이')}${statCard('▤',fmt(stats.sentences),'영어 학습 문장')}${statCard('◎',`${daily} / ${state.settings.dailyTarget}`,'오늘 살펴본 새 학습편')}</div><div class="section-heading"><div><h2>나에게 맞는 학습 과정</h2><p class="page-subtitle">기초 읽기에서 학술적 표현까지 두 가지 트랙으로 확장합니다.</p></div>${button('과정 모두 보기','goLibrary','btn-sm')}</div><div class="grid-cols-2"><article class="surface track-card"><div class="part-label">TRACK 01 / FOUNDATION → BRIDGE</div><h3>📘 Core Reading · 30편</h3><p>CEFR B1–B2. 어순대로 끊어 읽기, 시제·관계사·가정법 등 문법과 문장 이해에 집중합니다.</p><div class="card-count">완료 ${completed(core)} / 30</div><div class="progress"><span style="width:${completed(core)/30*100}%"></span></div><div class="mt16">${button('기초 트랙 보기 →','coreTrack','btn-sm btn-primary')}</div></article><article class="surface track-card"><div class="part-label">TRACK 02 / ACADEMIC REGISTER</div><h3>🎓 University · 30편</h3><p>CEFR C1. 같은 주제를 논증·인용·연구 보고·데이터 해석 등 학술 영어로 확장합니다.</p><div class="card-count">완료 ${completed(uni)} / 30</div><div class="progress"><span style="width:${completed(uni)/30*100}%"></span></div><div class="mt16">${button('대학 트랙 보기 →','uniTrack','btn-sm btn-primary')}</div></article></div><div class="section-heading"><div><h2>지금 시작하면 좋은 글</h2><p class="page-subtitle">최근 학습과 미완료 강의를 기준으로 추천합니다.</p></div></div><div class="grid-cards">${[recent,suggestion,getLesson(pair(recent))].filter((x,i,a)=>a.findIndex(z=>z.id===x.id)===i).map(lessonCard).join('')}</div><div class="section-heading"><h2>권장 학습 루틴</h2>${button('학습 방법','guide','btn-sm')}</div><div class="grid-cols-3"><div class="surface surface-pad"><span class="pill aqua">01 · 청크</span><h3 class="mt16">어순대로 이해</h3><p class="page-subtitle">청크로 끊어 읽고, 바로 한국어 의미를 확인합니다. 권장 3회.</p></div><div class="surface surface-pad"><span class="pill aqua">02 · 문장</span><h3 class="mt16">한 호흡 낭독</h3><p class="page-subtitle">영문만 먼저 보고 입으로 읽은 뒤 뜻을 확인합니다. 권장 3회.</p></div><div class="surface surface-pad"><span class="pill aqua">03 · 원문</span><h3 class="mt16">속도와 유창성</h3><p class="page-subtitle">처음부터 끝까지 낭독하며 타이머로 WPM을 기록합니다.</p></div></div></div>`}
function renderLibrary(){const list=lessons.filter(l=>{if(libraryFilter==='core'&&l.track!=='core')return false;if(libraryFilter==='university'&&l.track!=='university')return false;if(libraryFilter==='completed'&&!done(l.id))return false;if(libraryFilter==='favorites'&&!state.favorites[l.id])return false;const term=libraryQuery.trim().toLocaleLowerCase();return !term||[l.id,l.title,l.subtitle,l.meta['핵심 문법'],level(l)].some(s=>String(s||'').toLocaleLowerCase().includes(term));});if(libraryOrder==='latest')list.sort((a,b)=>(getProgress(b.id).lastVisit||0)-(getProgress(a.id).lastVisit||0));return `<div class="content-wide"><div class="eyebrow">THE COMPLETE LIBRARY</div><h1 class="page-title">60편 학습 라이브러리</h1><p class="page-subtitle">주제별로 연결된 30편의 기초·중급 글과 30편의 C1 학술 영어를 탐색하세요. 제목·문법·한국어 제목 검색을 지원합니다.</p><div class="filter-head"><div class="search-box"><span>⌕</span><input type="search" id="library-search" placeholder="제목·문법·키워드 검색" value="${attr(libraryQuery)}" aria-label="학습편 검색"></div><div class="filter-row">${[['all','전체 60편'],['core','Core 30'],['university','University 30'],['completed','완료'],['favorites','★ 즐겨찾기']].map(([k,v])=>`<button class="filter-chip ${libraryFilter===k?'active':''}" data-filter="${k}">${v}</button>`).join('')}</div></div><div class="flex space-between mb16"><span class="muted">${list.length}편 표시 중</span><select id="library-sort" aria-label="정렬 순서"><option value="sequence" ${libraryOrder==='sequence'?'selected':''}>학습 순서</option><option value="latest" ${libraryOrder==='latest'?'selected':''}>최근 학습순</option></select></div>${list.length?`<div class="grid-cards">${list.map(lessonCard).join('')}</div>`:empty('검색 결과가 없습니다','다른 검색어 또는 필터를 선택해 보세요.')}</div>`}
function modeBtn(mode,label,icon,current){return `<button type="button" class="mode-btn ${mode===current?'active':''}" data-mode="${mode}">${icon} ${label}</button>`}
function renderLesson(l,mode){const valid=['chunks','sentences','full','grammar','vocab','quiz','source'];mode=valid.includes(mode)?mode:'chunks';route.mode=mode;const p=getProgress(l.id);const idx=lessons.findIndex(x=>x.id===l.id);const isUni=l.track==='university';const section=mode==='chunks'?renderChunks(l):mode==='sentences'?renderSentences(l):mode==='full'?renderFull(l):mode==='grammar'?renderGrammar(l):mode==='vocab'?renderVocab(l):mode==='quiz'?renderQuiz(l):renderSource(l);return `<div class="content-wide"><section class="surface lesson-heading"><div class="flex space-between flex-wrap"><span class="eyebrow">${isUni?'UNIVERSITY TRACK / ACADEMIC READING':'CORE TRACK / CHUNK READING'} · LESSON ${e(l.id)}</span><div class="flex">${button(state.favorites[l.id]?'★ 즐겨찾기':'☆ 즐겨찾기','favorite','btn-sm',`data-id="${l.id}"`)}${button(p.completed?'✓ 완료됨':'학습 완료 표시','complete','btn-sm','data-id="'+l.id+'"')}</div></div><h1 class="lesson-title">${e(l.title)}</h1><p class="lesson-title-kr">${e(l.subtitle)}</p><div class="meta-detail"><span class="pill aqua">${e(level(l))}</span><span class="pill">${fmt(l.wordCount)} words</span><span class="pill">${l.sentences.length} sentences</span><span class="pill">${e(l.meta['문체']||'')}</span></div><p class="page-subtitle" style="font-size:12px"><b>핵심 학습:</b> ${e(l.meta['핵심 문법']||'')}</p><div class="divider" style="margin:15px 0"></div><div class="lesson-tool-row">${button('← 이전','previous','btn-sm',idx===0?'disabled':'')}${button('다음 →','next','btn-sm',idx===lessons.length-1?'disabled':'')}${button(`연결 학습 ${e(pair(l))} ↗`,'pair','btn-sm')}${button('문서 내려받기','downloadMarkdown','btn-sm')}${button('학습 메모','openNotes','btn-sm')}${button('본문으로 ↓','jumpStudy','btn-sm')}</div></section><nav class="mode-strip" aria-label="학습 단계">${modeBtn('chunks','청크 직독직해','◧',mode)}${modeBtn('sentences','문장 직독직해','▤',mode)}${modeBtn('full','원문 낭독','▥',mode)}${modeBtn('grammar',isUni?'학술 영어':'문법 해설','✦',mode)}${modeBtn('vocab','어휘 카드','◇',mode)}${modeBtn('quiz','이해도 퀴즈','✓',mode)}${modeBtn('source','전체 원본','☰',mode)}</nav>${['chunks','sentences','full','vocab'].includes(mode)?renderStudyToolbar(l,mode):''}<div id="lesson-study-content">${section}</div>${renderNotes(l)}</div>`}
function renderStudyToolbar(l,mode){let opt='';if(mode==='chunks'||mode==='sentences'){opt=`<label class="checkline"><input type="checkbox" data-setting="translation" ${state.settings.translation?'checked':''}> 한국어 해석 표시</label>${button(focus?'집중 학습 종료':'집중 학습','focusToggle','btn-sm')}`;}else if(mode==='full'){opt=button('원문 연속 듣기','listenAll','btn-sm btn-primary')+button('낭독 타이머로 기록','timerStart','btn-sm')}else opt='<span class="muted" style="font-size:12px">플래시카드를 눌러 뜻을 확인합니다.</span>';
const voiceOptions=getEnglishVoices();return `<div class="surface study-options"><div class="flex flex-wrap">${opt}</div><div class="flex flex-wrap"><span class="muted" style="font-size:12px">영어 TTS</span><select id="tts-voice" aria-label="음성 선택"><option value="">브라우저 기본 음성</option>${voiceOptions.map(v=>`<option value="${attr(v.voiceURI)}" ${state.settings.voice===v.voiceURI?'selected':''}>${e(v.name.slice(0,24))}</option>`).join('')}</select><select id="tts-speed" aria-label="읽기 속도">${[.5,.6,.7,.8,.9,1,1.1,1.2,1.3,1.5,1.7,2].map(s=>`<option value="${s}" ${Number(state.settings.speed)===s?'selected':''}>${s.toFixed(1)}×</option>`).join('')}</select>${button('▶ 전체 듣기','listenAll','btn-sm')}${button('Ⅱ','pauseTTS','btn-sm','aria-label="일시정지 / 재개"')}${button('■','stopTTS','btn-sm','aria-label="음성 정지"')}</div></div>`}
function renderChunks(l){const flat=l.chunks.flatMap(x=>x.rows);if(focus){const item=flat[Math.min(focusIndex,flat.length-1)]||{};return `<div class="focus-center"><div class="surface paragraph-card"><div class="flex space-between"><span class="pill aqua">청크 집중 학습</span><span class="muted">${Math.min(focusIndex+1,flat.length)} / ${flat.length}</span></div><div class="focus-single" data-audio-key="c-${focusIndex}"><div class="chunk-english">${e(item.en)}</div><div class="chunk-korean ${state.settings.translation?'':'hide-translation'}" title="눌러 해석 확인" data-act="reveal">${e(item.ko)}</div>${item.note?`<div class="chunk-note mt16">${e(item.note)}</div>`:''}</div></div><div class="focus-bar">${button('← 이전','focusPrev','btn-sm')}${button('▶ 듣기','focusSpeak','btn-sm')}${button('다음 →','focusNext','btn-sm')}${button('뜻 전환','toggleTranslation','btn-sm')}</div></div>`}
return `<div class="reading-area"><div class="learning-note"><strong>Step 1 · 청크 단위 직독직해</strong> 영어를 왼쪽부터 의미 단위로 받아들이세요. 청크를 읽고 뜻을 떠올린 뒤 오른쪽 해석과 비교합니다. <strong>3회 반복</strong>을 권장합니다.</div>${l.chunks.map((p,pidx)=>`<section class="surface paragraph-card"><div class="paragraph-top"><span class="paragraph-index">PARAGRAPH ${p.paragraph}</span><span class="pill">${p.rows.length} chunks</span></div>${p.rows.map((x,i)=>{const n=l.chunks.slice(0,pidx).reduce((a,b)=>a+b.rows.length,0)+i;return `<div class="chunk-row" data-audio-key="c-${n}"><div class="chunk-english">${e(x.en)}</div><div class="chunk-korean ${state.settings.translation?'':'hide-translation'}" title="눌러 해석 확인" data-act="reveal">${e(x.ko)}</div>${x.note?`<div class="chunk-note">${e(x.note)}</div>`:''}<button class="btn btn-sm btn-quiet chunk-tool" data-act="speakItem" data-kind="chunk" data-num="${n}" title="청크 듣기" aria-label="청크 듣기">▶</button></div>`}).join('')}</section>`).join('')}<p class="muted" style="text-align:center">모든 ${fmt(flat.length)}개 청크를 확인한 후 ‘문장 직독직해’로 넘어가세요.</p></div>`}
function renderSentences(l){if(focus){const n=Math.min(focusIndex,l.sentences.length-1),s=l.sentences[n];return `<div class="focus-center"><div class="surface paragraph-card"><div class="flex space-between"><span class="pill aqua">문장 집중 학습</span><span class="muted">${n+1} / ${l.sentences.length}</span></div><div class="focus-single" data-audio-key="s-${n}"><div class="chunk-english">${e(s.en)}</div><div class="chunk-korean ${state.settings.translation?'':'hide-translation'}" data-act="reveal">${e(s.ko)}</div><div class="chunk-note mt16">${e(s.note)}</div></div></div><div class="focus-bar">${button('← 이전','focusPrev','btn-sm')}${button('▶ 듣기','focusSpeak','btn-sm')}${button('다음 →','focusNext','btn-sm')}${button('뜻 전환','toggleTranslation','btn-sm')}</div></div>`}
return `<div class="reading-area"><div class="learning-note"><strong>Step 2 · 문장 단위 직독직해</strong> 한 문장을 한 호흡에 읽고 한국어 해석을 확인합니다. 뜻이 익숙한 문장은 ‘익힘’으로 체크해 두세요. <strong>3회 반복</strong>을 권장합니다.</div>${l.sentences.map((s,i)=>`<article class="surface sentence-card" data-audio-key="s-${i}"><div class="sentence-actions"><span class="sentence-num">${String(i+1).padStart(2,'0')} · 문단 ${s.paragraph}</span><span class="chipbar"><span class="pill ${state.known[`${l.id}:${i}`]?'aqua':''}">${state.known[`${l.id}:${i}`]?'✓ 익힘':'학습 중'}</span></span></div><div class="sentence-english">${e(s.en)}</div><div class="sentence-korean ${state.settings.translation?'':'hide-translation'}" title="눌러 뜻 확인" data-act="reveal">${e(s.ko)}</div>${s.note?`<div class="sentence-note">어휘: ${e(s.note)}</div>`:''}<div class="sentence-foot">${button('▶ 듣기','speakItem','btn-sm',`data-kind="sentence" data-num="${i}"`)}${button(state.saved[`${l.id}:${i}`]?'★ 저장됨':'☆ 복습 저장','saveSentence','btn-sm',`data-num="${i}"`)}${button(state.known[`${l.id}:${i}`]?'✓ 익힘':'익힘 표시','knowSentence','btn-sm',`data-num="${i}"`)}</div></article>`).join('')}</div>`}
function renderFull(l){const p=getProgress(l.id),readings=p.readings||[];return `<div class="reading-area"><div class="learning-note"><strong>Step 3 · 원문 낭독</strong> 전체 글을 처음부터 끝까지 소리 내어 읽어 보세요. 아래의 타이머에서 기록하면 읽기 속도(WPM)가 자동 계산됩니다. 권장 <strong>3회 이상</strong>입니다.</div><div class="surface record-box"><span class="pill aqua">NARRATION TIMER</span><span id="reading-timer" class="timer">00:00</span><span class="muted">${fmt(l.wordCount)} 단어</span><div class="ml-auto flex flex-wrap">${button('▶ 시작','timerStart','btn-sm btn-primary')}${button('■ 완료·기록','timerStop','btn-sm')}${button('⟲ 초기화','timerReset','btn-sm')}</div></div><article class="surface full-reading" id="full-reading" lang="en"><div class="eyebrow" style="margin-bottom:17px">FULL TEXT · ${e(l.id)}</div>${l.original.map(para=>/^\*\*(.*?)\*\*$/.test(para)?`<div class="day-heading">${e(strip(para))}</div>`:`<p class="reader-paragraph">${e(strip(para))}</p>`).join('')}</article><div class="surface surface-pad mt16"><h3>나의 낭독 기록</h3>${readings.length?`<div style="overflow-x:auto"><table class="wpm-table"><thead><tr><th>회차</th><th>날짜</th><th>읽기 시간</th><th>WPM</th></tr></thead><tbody>${[...readings].reverse().map((x,i)=>`<tr><td>${readings.length-i}회</td><td>${e(x.date)}</td><td>${timeFormat(x.seconds)}</td><td><b>${x.wpm}</b></td></tr>`).join('')}</tbody></table></div>`:empty('아직 기록이 없습니다','타이머를 시작하고 글을 낭독한 후 완료·기록을 눌러 주세요.')}</div></div>`}
function renderGrammar(l){const raw=l.source;let head=l.track==='university'?'학술 영어 포인트':'문법 포인트';const cut=sectionBetween(raw,`## ${head}`,'## 핵심 어휘');const ref=sectionBetween(raw,'## 참고 문헌','## 학술 영어 포인트');const extra=l.track==='university'?extractExtras(raw):'';return `<div class="content-narrow"><div class="learning-note"><strong>${e(head)}</strong> 원본 자료의 표, 예문, 설명을 포함합니다. ${l.track==='university'?'논증 구조와 원작 비교를 살펴보세요.':'문장 속 문법 구조가 어떻게 작동하는지 확인하세요.'}</div>${ref?`<details class="surface surface-pad" style="margin-bottom:15px"><summary style="cursor:pointer;font-weight:800">📚 참고 문헌 (${e(l.id)})</summary><div class="md-body" style="margin-top:14px">${md(ref)}</div></details>`:''}<div class="md-body">${md('## '+head+'\n\n'+cut)}</div>${extra?`<details class="surface surface-pad mt16"><summary style="cursor:pointer;font-weight:750">추가 자료·사례·표 펼치기</summary><div class="md-body mt16">${md(extra)}</div></details>`:''}</div>`}
function sectionBetween(source,a,b){const i=source.indexOf(a);if(i<0)return '';const s=source.slice(i+a.length).replace(/^.*\n/,'');const j=s.indexOf(b);return (j>=0?s.slice(0,j):s).replace(/---\s*$/,'').trim()}
function extractExtras(source){const slice=sectionBetween(source,'## 2회차','## 학술 영어 포인트');const m=slice.search(/\n## (?!참고 문헌)/);const k=slice.indexOf('\n## 참고 문헌');return m>=0&&k<0?slice.slice(m).trim():''}
function renderVocab(l){const words=l.vocabulary;const i=((flipIndex%words.length)+words.length)%words.length;const w=words[i];return `<div class="content-narrow"><div class="learning-note"><strong>어휘 학습</strong> ${words.length}개의 핵심 어휘. 카드를 눌러 뜻을 확인하고, 익숙해진 단어는 ‘외움’ 버튼을 눌러 표시하세요. 원본 어휘장도 아래에 그대로 제공합니다.</div><div style="max-width:610px;margin:0 auto 20px"><div class="flex space-between mb16"><span class="pill aqua">FLASHCARD ${i+1} / ${words.length}</span><span class="pill">외움 ${words.filter((w,j)=>state.wordKnown[`${l.id}:${j}`]).length}/${words.length}</span></div><button type="button" class="flashcard" style="width:100%;color:var(--ink)" data-act="flipCard"><div><div class="hint">${flipped?'KOREAN MEANING':'ENGLISH VOCABULARY'}</div><div class="vocab-front" lang="en">${e(w.en)}</div><div class="vocab-back" ${flipped?'':'style="filter:blur(7px);color:var(--muted)"'}>${flipped?e(w.ko):'탭하여 뜻 확인'}</div></div></button><div class="flex space-between mt16 flex-wrap">${button('← 이전','wordPrev','btn-sm')}${button('▶ 발음','wordSpeak','btn-sm')}${button(state.wordKnown[`${l.id}:${i}`]?'✓ 외움':'외움 표시','wordKnown','btn-sm btn-primary')}${button('다음 →','wordNext','btn-sm')}</div></div><div class="section-heading"><h2>전체 단어장</h2><span class="pill">${words.length}개</span></div><div class="vocab-grid">${words.map((x,j)=>`<div class="vocab-card"><div><b>${e(x.en)}</b><span>${e(x.ko)}</span></div><button type="button" class="btn btn-sm" data-act="speakItem" data-kind="word" data-num="${j}" aria-label="${e(x.en)} 발음">▶</button></div>`).join('')}</div></div>`}
function newQuiz(l){const order=l.sentences.map((_,i)=>i).sort(()=>Math.random()-.5).slice(0,Math.min(10,l.sentences.length));quiz={id:l.id,items:order.map(k=>{const other=l.sentences.map((_,i)=>i).filter(i=>i!==k&&l.sentences[i].ko!==l.sentences[k].ko).sort(()=>Math.random()-.5).slice(0,3);return{correct:k,choices:[k,...other].sort(()=>Math.random()-.5)}}),index:0,answers:[],selected:null}}
function renderQuiz(l){if(!quiz||quiz.id!==l.id)newQuiz(l);const q=quiz;if(q.index>=q.items.length){const score=q.answers.filter(Boolean).length;return `<div class="quiz-panel surface"><div class="result-hero"><span class="pill aqua">QUIZ COMPLETE</span><div class="score">${Math.round(100*score/q.items.length)}<small style="font-size:24px">%</small></div><h2>문장 해석 퀴즈 완료!</h2><p class="page-subtitle">정답 ${score} / ${q.items.length}개 · ${score===q.items.length?'완벽합니다!':'틀린 문장을 복습하면 더 효과적입니다.'}</p><div class="flex flex-wrap" style="justify-content:center;margin-top:20px">${button('다시 도전','resetQuiz','btn-primary')}${button('문장 복습하기','reviewMissed','')}</div></div></div>`}const item=q.items[q.index],s=l.sentences[item.correct],answered=q.selected!==null;return `<div class="quiz-panel surface"><div class="flex space-between flex-wrap"><span class="pill aqua">SENTENCE COMPREHENSION</span><span class="muted">문제 ${q.index+1} / ${q.items.length}</span></div><div class="progress mt16"><span style="width:${100*q.index/q.items.length}%"></span></div><h2 style="margin:25px 0 9px;font-size:20px">아래 영어 문장의 의미는?</h2><div class="quiz-en" lang="en">${e(s.en)}</div><div class="quiz-options">${item.choices.map((n,j)=>`<button type="button" class="quiz-choice ${answered?(n===item.correct?'correct':j===q.selected?'incorrect':''):''}" data-choice="${j}" ${answered?'disabled':''}><span class="pill">${j+1}</span><span>${e(l.sentences[n].ko)}</span>${answered&&n===item.correct?' <b>✓</b>':''}</button>`).join('')}</div>${answered?`<div class="quiz-explain"><b>${item.choices[q.selected]===item.correct?'✓ 정답입니다.':'다시 읽어 보세요.'}</b><div class="mt8">${e(s.ko)}</div>${s.note?`<small>어휘: ${e(s.note)}</small>`:''}</div><div class="flex" style="justify-content:flex-end;margin-top:16px">${button(q.index+1===q.items.length?'결과 보기':'다음 문제 →','quizNext','btn-primary')}</div>`:''}</div>`}
function renderSource(l){return `<div class="content-narrow"><div class="learning-note"><strong>원본 전체 보기</strong> 첨부 파일의 마크다운 원문을 빠짐없이 변환해 표시합니다. 원본 텍스트 파일은 ‘문서 내려받기’에서 저장할 수 있습니다.</div><div class="md-body">${md(l.source)}</div></div>`}
function renderNotes(l){const text=state.notes[l.id]||'';return `<details class="surface surface-pad mt24" id="notes-box"><summary style="cursor:pointer;font-weight:800">✎ 개인 메모 (${text.length?text.length+'자':'미작성'})</summary><p class="page-subtitle mt16">중요한 문장, 발음 팁, 문법 질문을 자유롭게 기록하세요. 메모는 이 기기의 브라우저에만 저장됩니다.</p><textarea id="lesson-notes" rows="5" placeholder="학습 메모를 적어 보세요…">${e(text)}</textarea><div class="muted mt8" style="font-size:12px">입력과 동시에 자동 저장됩니다.</div></details>`}
function renderReview(){const items=Object.keys(state.saved).filter(k=>state.saved[k]&&byId[k.split(':')[0]]).map(k=>{const [id,n]=k.split(':');return{id,n:Number(n),s:byId[id]?.sentences[Number(n)],title:byId[id]?.title}}).filter(x=>x.s);const learned=items.filter(x=>state.known[`${x.id}:${x.n}`]).length;return `<div class="content-narrow"><div class="eyebrow">MY PERSONAL REVIEW</div><h1 class="page-title">나의 복습함</h1><p class="page-subtitle">읽다가 저장한 문장을 다시 듣고 뜻을 확인하세요. 익힌 문장은 별도로 표시됩니다.</p><div class="grid-cols-2 mt16">${statCard('☆',fmt(items.length),'복습 저장 문장')}${statCard('✓',fmt(learned),'익힌 저장 문장')}</div><div class="section-heading"><h2>저장한 문장</h2><span class="pill">${items.length}개</span></div>${items.length?`<div class="stack">${items.map(x=>`<article class="review-item surface"><div class="body"><div class="eyebrow">${e(x.id)} · ${x.n+1}번째 문장</div><h3>${e(x.s.en)}</h3><p>${e(x.s.ko)}</p><small>${e(x.title)}</small></div><div class="stack" style="gap:6px">${button('▶','reviewSpeak','btn-sm',`data-id="${x.id}" data-num="${x.n}"`)}${button(state.known[`${x.id}:${x.n}`]?'✓':'○','reviewKnow','btn-sm',`data-id="${x.id}" data-num="${x.n}"`)}${button('×','reviewRemove','btn-sm',`data-id="${x.id}" data-num="${x.n}"`)}</div></article>`).join('')}</div>`:empty('저장한 문장이 없습니다','학습실의 ‘문장 직독직해’에서 ☆ 복습 저장을 눌러 보세요.')}</div>`}
function renderStats(){const doneN=completed(lessons),sessions=Object.values(state.progress).flatMap(v=>v.readings||[]);const best=sessions.length?Math.max(...sessions.map(x=>x.wpm||0)):0;const days=Object.entries(state.daily).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,14);const uni=completed(lessons.filter(x=>x.track==='university'));return `<div class="content-narrow"><div class="eyebrow">LEARNING ANALYTICS</div><h1 class="page-title">학습 성장 기록</h1><p class="page-subtitle">실제 학습 기록 기반 통계입니다. 완료 표시는 수동이며, WPM은 타이머 기록으로 계산됩니다.</p><div class="grid-cols-3 mt16">${statCard('✓',doneN+'/60','완료한 학습편')}${statCard('◎',sessions.length,'낭독 기록 횟수')}${statCard('↗',best||'—','최고 읽기 속도 WPM')}</div><div class="section-heading"><h2>과정별 완료율</h2></div><div class="surface surface-pad"><div class="flex space-between"><b>Core Reading</b><span>${doneN-uni} / 30</span></div><div class="progress mt8"><span style="width:${(doneN-uni)/30*100}%"></span></div><div class="flex space-between mt24"><b>University Track</b><span>${uni} / 30</span></div><div class="progress mt8"><span style="width:${uni/30*100}%"></span></div></div><div class="section-heading"><h2>최근 14일 학습 이력</h2></div>${days.length?`<div class="surface surface-pad"><table class="detail-table"><tbody>${days.map(([d,v])=>`<tr><td>${e(d)}</td><td>${v}편 학습 시작</td></tr>`).join('')}</tbody></table></div>`:empty('학습 이력이 없습니다','강의를 열어 학습을 시작해 보세요.')}<div class="section-heading"><h2>최근 낭독 기록</h2></div>${sessions.length?`<div class="surface surface-pad"><table class="wpm-table"><thead><tr><th>날짜</th><th>학습편</th><th>WPM</th></tr></thead><tbody>${Object.entries(state.progress).flatMap(([id,p])=>(p.readings||[]).map(r=>({...r,id}))).sort((a,b)=>(b.timestamp||0)-(a.timestamp||0)).slice(0,15).map(x=>`<tr><td>${e(x.date)}</td><td>${e(x.id)}</td><td><b>${x.wpm}</b></td></tr>`).join('')}</tbody></table></div>`:empty('낭독 기록이 없습니다','학습실의 원문 낭독에서 타이머를 사용해 주세요.')}</div>`}
function renderSettings(){return `<div class="content-narrow"><div class="eyebrow">YOUR PREFERENCES</div><h1 class="page-title">학습 환경 설정</h1><p class="page-subtitle">글자 크기, 표시 방식, 음성 속도, 일일 목표를 선택할 수 있습니다. 모든 변경은 자동 저장됩니다.</p><div class="settings-grid mt16"><section class="surface settings-card"><span class="pill aqua">독서 화면</span><h3 class="mt16">읽기 편안함</h3><div class="setting-field"><label for="font-range">글자 크기 · <output id="font-out">${state.settings.font}px</output></label><input type="range" id="font-range" data-setting="font" min="15" max="27" step="1" value="${state.settings.font}"></div><div class="setting-field"><label for="line-range">줄 간격 · <output id="line-out">${Number(state.settings.line).toFixed(2)}</output></label><input type="range" id="line-range" data-setting="line" min="1.45" max="2.4" step="0.05" value="${state.settings.line}"></div><label class="checkline"><input type="checkbox" data-setting="translation" ${state.settings.translation?'checked':''}> 한국어 번역 기본 표시</label></section><section class="surface settings-card"><span class="pill aqua">음성 · 목표</span><h3 class="mt16">학습 루틴</h3><div class="setting-field"><label for="default-speed">TTS 속도</label><select id="default-speed" data-setting="speed">${[.5,.6,.7,.8,.9,1,1.1,1.2,1.3,1.5,1.7,2].map(s=>`<option value="${s}" ${Number(state.settings.speed)===s?'selected':''}>${s}배속</option>`).join('')}</select></div><div class="setting-field"><label for="daily-target">하루 새 학습편 목표</label><select id="daily-target" data-setting="dailyTarget">${[1,2,3,4,5,7,10].map(s=>`<option value="${s}" ${state.settings.dailyTarget==s?'selected':''}>${s}편</option>`).join('')}</select></div><div class="setting-field"><label for="theme-select">화면 테마</label><select id="theme-select" data-setting="theme"><option value="light" ${state.settings.theme==='light'?'selected':''}>라이트 모드</option><option value="dark" ${state.settings.theme==='dark'?'selected':''}>다크 모드</option></select></div></section><section class="surface settings-card"><span class="pill gold">저장 · 내보내기</span><h3 class="mt16">내 학습 기록</h3><p>진도·즐겨찾기·복습 문장·개인 메모·설정 등을 JSON 파일로 백업합니다. 다른 기기에서 불러올 수 있습니다.</p><div class="stack mt16">${button('↓ 학습 기록 백업','exportData','')}${button('↑ 백업 기록 불러오기','importData','')}<input type="file" id="import-file" accept=".json,application/json" hidden>${button('학습 데이터 초기화','clearData','btn-danger')}</div></section><section class="surface settings-card"><span class="pill">ACCESS</span><h3 class="mt16">로그인 정보</h3><p>이 사이트는 별도 서버 없이 동작합니다. 단순 클라이언트 비밀번호는 데이터 접근을 안전하게 차단하지 못합니다.</p><div class="stack mt16">${button('현재 기기에서 로그아웃','logout','')}${button('학습 방법·도움말','guide','')}</div></section></div></div>`}
function renderGuide(){const idx=window.STUDIO_DATA.indexes||{};return `<div class="content-narrow"><div class="eyebrow">GETTING STARTED</div><h1 class="page-title">학습 방법 안내</h1><div class="learning-note"><strong>추천 흐름:</strong> Core 01 → University U01을 연달아 읽으면 같은 주제가 기초 영어와 학술 영어에서 어떻게 달라지는지 비교할 수 있습니다. 한 편마다 청크 3회 → 문장 3회 → 원문 3회 낭독을 권장합니다.</div><div class="grid-cols-2 mt16"><div class="surface surface-pad"><h3>기능별 요약</h3><p class="page-subtitle">청크·문장 번역 숨김, 영어 TTS 낭독, 이어 듣기, 문장 저장, 플래시카드, 의미 선택 퀴즈, WPM 타이머, 개인 메모, 완료 체크, 오프라인 PWA(접속 후 캐시) 기능을 제공합니다.</p></div><div class="surface surface-pad"><h3>알아두기</h3><p class="page-subtitle">영어 음성은 브라우저 TTS이며 원어민 녹음 음원은 포함되지 않았습니다. 음성 품질과 오프라인 TTS 지원은 운영체제·브라우저에 따라 달라집니다. 학습 기록은 브라우저에 저장되며 기기 간 자동 동기화되지 않습니다.</p></div></div><div class="section-heading"><h2>Core 30편 원본 학습 목차</h2></div><div class="md-body">${md(idx['00_Series_Index.md']||'')}</div><div class="section-heading"><h2>University 30편 원본 학습 목차</h2></div><div class="md-body">${md(idx['00U_University_Track_Index.md']||'')}</div></div>`}
// Conservative Markdown renderer for locally bundled learning materials: escaped source + allowlisted markup.
function mdInline(raw){let s=e(raw);s=s.replace(/`([^`]+)`/g,'<code>$1</code>');s=s.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');s=s.replace(/(?<!\*)\*([^*\n]+)\*(?!\*)/g,'<em>$1</em>');s=s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,(_,t,u)=>`<a href="${attr(u)}" target="_blank" rel="noopener noreferrer">${t} ↗</a>`);return s;}
function md(text){const lines=String(text||'').split(/\r?\n/),out=[];let i=0;while(i<lines.length){const a=lines[i],t=a.trim();if(!t){i++;continue;}if(/^```/.test(t)){const a=[];i++;while(i<lines.length&&!/^```/.test(lines[i]))a.push(lines[i++]);out.push(`<pre><code>${e(a.join('\n'))}</code></pre>`);i++;continue;}if(/^\|/.test(t)&&i+1<lines.length&&/\|\s*:?-{2,}/.test(lines[i+1])){let rows=[];while(i<lines.length&&lines[i].trim().startsWith('|')){const cl=lines[i].trim().replace(/^\||\|$/g,'').split('|').map(s=>s.trim());if(!cl.every(s=>/^:?-{2,}:?$/.test(s)))rows.push(cl);i++}if(rows.length){const [head,...tail]=rows;out.push(`<div class="table-scroll"><table><thead><tr>${head.map(x=>`<th>${mdInline(x)}</th>`).join('')}</tr></thead><tbody>${tail.map(row=>`<tr>${row.map(x=>`<td>${mdInline(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`)}continue;}const h=t.match(/^(#{1,4})\s+(.+)/);if(h){const n=Math.min(3,h[1].length);out.push(`<h${n}>${mdInline(h[2])}</h${n}>`);i++;continue;}if(/^---+$/.test(t)){out.push('<div class="md-separator"></div>');i++;continue;}if(/^>/.test(t)){const arr=[];while(i<lines.length&&lines[i].trim().startsWith('>')){arr.push(lines[i].trim().replace(/^>\s?/,''));i++}out.push(`<blockquote>${arr.map(x=>x?`<p>${mdInline(x)}</p>`:'').join('')}</blockquote>`);continue;}if(/^([-*] |\d+\. )/.test(t)){const ordered=/^\d+\. /.test(t);const items=[];while(i<lines.length&&/^\s*([-*] |\d+\. )/.test(lines[i])){items.push(lines[i].trim().replace(/^([-*] |\d+\. )/,''));i++}out.push(`<${ordered?'ol':'ul'}>${items.map(x=>`<li>${mdInline(x)}</li>`).join('')}</${ordered?'ol':'ul'}>`);continue;}const p=[t];i++;while(i<lines.length&&lines[i].trim()&&!/^(#{1,4}\s|\||>|---|```|[-*] |\d+\. )/.test(lines[i].trim()))p.push(lines[i++].trim());out.push(`<p>${mdInline(p.join(' '))}</p>`);}return out.join('\n');}
function updateView({scroll=false}={}){const y=window.scrollY;render();if(!scroll)window.scrollTo({top:y})}
function getEnglishVoices(){return ttsVoices.filter(v=>(v.lang||'').toLowerCase().startsWith('en'))}
function initVoices(){if(!('speechSynthesis'in window))return;const reload=()=>{ttsVoices=window.speechSynthesis.getVoices()||[];const sel=$('#tts-voice');if(sel){const value=state.settings.voice;sel.innerHTML='<option value="">브라우저 기본 음성</option>'+getEnglishVoices().map(v=>`<option value="${attr(v.voiceURI)}" ${value===v.voiceURI?'selected':''}>${e(v.name.slice(0,24))}</option>`).join('')}};reload();window.speechSynthesis.addEventListener?.('voiceschanged',reload);}
let audioToken=0;
function stopTTS(){audioToken++;audioQueue=[];audioPos=0;paused=false;if('speechSynthesis'in window)window.speechSynthesis.cancel();document.querySelectorAll('.active-speaking').forEach(x=>x.classList.remove('active-speaking'))}
function playItems(items){if(!('speechSynthesis'in window)){toast('이 브라우저는 음성합성을 지원하지 않습니다. Chrome 또는 Edge를 권장합니다.');return}stopTTS();audioQueue=items.map(a=>({...a,text:strip(a.text)})).filter(x=>x.text);if(!audioQueue.length){toast('재생할 문장이 없습니다.');return}const token=audioToken;playNext(token)}
function playNext(token){if(token!==audioToken)return;if(audioPos>=audioQueue.length){document.querySelectorAll('.active-speaking').forEach(el=>el.classList.remove('active-speaking'));audioQueue=[];return}const item=audioQueue[audioPos++];const synth=window.speechSynthesis;const utter=new SpeechSynthesisUtterance(item.text);utter.lang=item.lang||'en-US';utter.rate=Number(state.settings.speed)||0.9;utter.pitch=1;const voice=ttsVoices.find(v=>v.voiceURI===state.settings.voice)||getEnglishVoices().find(v=>v.lang==='en-US')||getEnglishVoices()[0];if(voice&&item.lang!=='ko-KR')utter.voice=voice;document.querySelectorAll('.active-speaking').forEach(el=>el.classList.remove('active-speaking'));if(item.key){const el=document.querySelector(`[data-audio-key="${item.key}"]`);if(el){el.classList.add('active-speaking');if(audioQueue.length<80)el.scrollIntoView({behavior:'smooth',block:'nearest'})}}utter.onend=()=>{if(token===audioToken){if(paused)return;playNext(token)}};utter.onerror=event=>{if(token===audioToken&&event.error!=='canceled'&&event.error!=='interrupted'){playNext(token)}};try{synth.speak(utter)}catch{toast('음성 재생에 실패했습니다. 브라우저 음성 설정을 확인하세요.');stopTTS()}}
function togglePauseTTS(){if(!('speechSynthesis'in window))return;const synth=window.speechSynthesis;if(synth.paused){synth.resume();paused=false;}else if(synth.speaking){synth.pause();paused=true}else if(audioQueue.length){paused=false;playNext(audioToken)}else toast('먼저 문장 또는 전체 듣기를 시작하세요.')}
function speakAll(){const l=getLesson(route.id),mode=route.mode;let items=[];if(mode==='chunks')items=l.chunks.flatMap(x=>x.rows).map((x,i)=>({text:x.en,key:`c-${i}`}));else if(mode==='vocab')items=l.vocabulary.map((x,i)=>({text:x.en,key:`w-${i}`}));else items=l.sentences.map((s,i)=>({text:s.en,key:`s-${i}`}));playItems(items)}
function speakOne(kind,num,l=getLesson(route.id)){let x='',key='';if(kind==='chunk'){const flat=l.chunks.flatMap(p=>p.rows);x=flat[num]?.en||'';key=`c-${num}`}else if(kind==='word'){x=l.vocabulary[num]?.en||'';key=`w-${num}`}else{x=l.sentences[num]?.en||'';key=`s-${num}`}playItems([{text:x,key}])}
function timeFormat(sec){const s=Math.max(0,Math.floor(sec||0));return`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function updateTimer(){const el=$('#reading-timer');if(el)el.textContent=timeFormat(timerStart?(Date.now()-timerStart)/1000:0)}
function startTimer(){if(timerStart){toast('타이머가 이미 실행 중입니다.');return;}timerStart=Date.now();clearInterval(timerTicker);timerTicker=setInterval(updateTimer,500);updateTimer();toast('낭독 타이머 시작 · 원문을 소리 내어 읽어 보세요.')}
function stopTimer(record=true){if(!timerStart)return;const seconds=Math.round((Date.now()-timerStart)/1000);timerStart=0;clearInterval(timerTicker);timerTicker=0;updateTimer();if(record&&route.page==='lesson'&&seconds>=3){const l=getLesson(route.id);const wpm=Math.round(l.wordCount*60/seconds);const p=state.progress[l.id]||{};p.readings=p.readings||[];p.readings.push({date:today(),timestamp:Date.now(),seconds,wpm});state.progress[l.id]=p;save();updateView();toast(`낭독 기록 저장! ${wpm} WPM · ${timeFormat(seconds)}`)}else if(record)toast('3초 이상의 낭독 기록만 저장합니다.')}
function downloadFile(filename,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('클립보드에 복사했습니다.')}catch{const x=document.createElement('textarea');x.value=text;document.body.appendChild(x);x.select();document.execCommand('copy');x.remove();toast('복사했습니다.')}}
function showNotes(){const el=$('#notes-box');if(el){el.open=true;el.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>$('#lesson-notes')?.focus(),200)}}
function registerQuiz(l){const score=quiz.answers.filter(Boolean).length;const pct=Math.round(score/quiz.items.length*100);state.quizHistory[l.id]=Math.max(state.quizHistory[l.id]||0,pct);save()}
function choiceAnswer(i){if(route.page!=='lesson'||route.mode!=='quiz'||!quiz||quiz.selected!==null)return;const q=quiz.items[quiz.index],correct=q.choices[i]===q.correct;quiz.selected=i;quiz.answers.push(correct);if(!correct){state.saved[`${route.id}:${q.correct}`]=true;save()}updateView()}
function keyForSentence(id,i){return`${id}:${i}`}
const modalOpen=()=>{const dlg=$('#help-dialog');if(dlg&&!dlg.open)dlg.showModal?.()};
function doAction(act,el){const l=getLesson(route.id);const id=el.dataset.id||l.id;const n=Number(el.dataset.num||0);switch(act){
case 'goRecent':go(`lesson/${state.recent||'01'}/chunks`);break;
case 'goLibrary':go('library');break;
case 'coreTrack':libraryFilter='core';go('library');break;
case 'uniTrack':libraryFilter='university';go('library');break;
case 'guide':go('guide');break;
case 'theme':state.settings.theme=state.settings.theme==='dark'?'light':'dark';save();updateView();break;
case 'help':modalOpen();break;
case 'closeHelp':$('#help-dialog')?.close();break;
case 'logout':stopTTS();stopTimer(false);sessionStorage.removeItem(LOGIN);localStorage.removeItem(REMEMBER);renderLogin();break;
case 'favorite':state.favorites[id]=!state.favorites[id];save();updateView();break;
case 'complete':{const p=state.progress[id]||{};p.completed=!p.completed;state.progress[id]=p;save();updateView();toast(p.completed?'학습 완료로 표시했습니다.':'완료 표시를 해제했습니다.');break}
case 'previous':{const i=lessons.findIndex(x=>x.id===l.id);if(i>0){focus=false;focusIndex=0;go(`lesson/${lessons[i-1].id}/chunks`)}}break;
case 'next':{const i=lessons.findIndex(x=>x.id===l.id);if(i<lessons.length-1){focus=false;focusIndex=0;go(`lesson/${lessons[i+1].id}/chunks`)}}break;
case 'pair':focus=false;focusIndex=0;go(`lesson/${pair(l)}/chunks`);break;
case 'downloadMarkdown':downloadFile(l.sourceFilename,l.source);break;
case 'openNotes':showNotes();break;
case 'jumpStudy':$('#lesson-study-content')?.scrollIntoView({behavior:'smooth',block:'start'});break;
case 'focusToggle':focus=!focus;focusIndex=0;updateView();break;
case 'focusNext':{const max=route.mode==='sentences'?l.sentences.length:l.chunks.reduce((a,p)=>a+p.rows.length,0);focusIndex=Math.min(max-1,focusIndex+1);updateView();break}
case 'focusPrev':focusIndex=Math.max(0,focusIndex-1);updateView();break;
case 'focusSpeak':speakOne(route.mode==='sentences'?'sentence':'chunk',focusIndex);break;
case 'toggleTranslation':state.settings.translation=!state.settings.translation;save();updateView();break;
case 'reveal':el.classList.toggle('hide-translation');break;
case 'speakItem':speakOne(el.dataset.kind,n);break;
case 'listenAll':speakAll();break;
case 'pauseTTS':togglePauseTTS();break;
case 'stopTTS':stopTTS();break;
case 'timerStart':startTimer();break;
case 'timerStop':stopTimer(true);break;
case 'timerReset':stopTimer(false);toast('낭독 타이머를 초기화했습니다.');break;
case 'saveSentence':state.saved[keyForSentence(l.id,n)]=!state.saved[keyForSentence(l.id,n)];save();updateView();break;
case 'knowSentence':state.known[keyForSentence(l.id,n)]=!state.known[keyForSentence(l.id,n)];save();updateView();break;
case 'flipCard':flipped=!flipped;updateView();break;
case 'wordNext':flipIndex=(flipIndex+1)%l.vocabulary.length;flipped=false;updateView();break;
case 'wordPrev':flipIndex=(flipIndex+l.vocabulary.length-1)%l.vocabulary.length;flipped=false;updateView();break;
case 'wordSpeak':speakOne('word',flipIndex);break;
case 'wordKnown':state.wordKnown[`${l.id}:${flipIndex}`]=!state.wordKnown[`${l.id}:${flipIndex}`];save();updateView();break;
case 'quizNext':if(quiz&&quiz.selected!==null){quiz.index++;quiz.selected=null;if(quiz.index===quiz.items.length)registerQuiz(l);updateView()}break;
case 'resetQuiz':newQuiz(l);updateView();break;
case 'reviewMissed':go(`lesson/${l.id}/sentences`);break;
case 'reviewSpeak':speakOne('sentence',n,getLesson(id));break;
case 'reviewKnow':state.known[`${id}:${n}`]=!state.known[`${id}:${n}`];save();updateView();break;
case 'reviewRemove':delete state.saved[`${id}:${n}`];save();updateView();break;
case 'exportData':downloadFile(`chunk-reading-backup-${today()}.json`,JSON.stringify({format:'chunk-reading-studio-v1',exportedAt:new Date().toISOString(),state},null,2),'application/json;charset=utf-8');toast('학습 기록을 백업했습니다.');break;
case 'importData':$('#import-file')?.click();break;
case 'clearData':if(confirm('학습 진도, 즐겨찾기, 메모, 퀴즈 기록을 모두 삭제할까요? 삭제 전 백업을 권장합니다.')){localStorage.removeItem(STORE);state.progress={};state.saved={};state.known={};state.notes={};state.quizHistory={};state.daily={};state.favorites={};state.wordKnown={};state.recent='';save();updateView();toast('학습 데이터를 초기화했습니다.')}break;
}}
// delegated controls: safe when the view is re-rendered
root.addEventListener('click',ev=>{const goEl=ev.target.closest('[data-go]');if(goEl){go(goEl.dataset.go);return}const modeEl=ev.target.closest('[data-mode]');if(modeEl){focus=false;focusIndex=0;flipIndex=0;flipped=false;quiz=null;go(`lesson/${route.id}/${modeEl.dataset.mode}`);return}const filter=ev.target.closest('[data-filter]');if(filter){libraryFilter=filter.dataset.filter;updateView();return}const q=ev.target.closest('[data-choice]');if(q){choiceAnswer(Number(q.dataset.choice));return}const act=ev.target.closest('[data-act]');if(act)doAction(act.dataset.act,act);});
root.addEventListener('input',ev=>{const el=ev.target;if(el.id==='library-search'){libraryQuery=el.value;const pos=el.selectionStart;updateView();const target=$('#library-search');target?.focus();try{target?.setSelectionRange(pos,pos)}catch{}return}if(el.id==='lesson-notes'){state.notes[route.id]=el.value;save();return}if(el.dataset.setting==='font'||el.dataset.setting==='line'){state.settings[el.dataset.setting]=Number(el.value);save();applySettings();if(el.id==='font-range')$('#font-out').textContent=`${el.value}px`;else $('#line-out').textContent=Number(el.value).toFixed(2)}});
root.addEventListener('change',ev=>{const el=ev.target;if(el.id==='library-sort'){libraryOrder=el.value;updateView();return}if(el.id==='tts-voice'){state.settings.voice=el.value;save();return}if(el.id==='tts-speed'){state.settings.speed=Number(el.value);save();return}if(el.dataset.setting){const k=el.dataset.setting;state.settings[k]=el.type==='checkbox'?el.checked:['font','line','speed','dailyTarget'].includes(k)?Number(el.value):el.value;save();updateView();return}if(el.id==='import-file'&&el.files?.length){const file=el.files[0];if(file.size>10*1024*1024){toast('10MB 이하의 JSON 백업만 불러올 수 있습니다.');return}file.text().then(text=>{const payload=JSON.parse(text);if(payload.format!=='chunk-reading-studio-v1'||!payload.state||typeof payload.state!=='object')throw Error('invalid');if(!confirm('현재 학습 기록을 백업 파일로 교체할까요?'))return;const imported=payload.state;for(const k of ['settings','progress','saved','known','notes','quizHistory','daily','recent','favorites','wordKnown'])if(Object.prototype.hasOwnProperty.call(imported,k))state[k]=imported[k];state.settings=Object.assign({},defaultSettings,state.settings||{});save();updateView();toast('학습 기록을 불러왔습니다.');}).catch(()=>toast('유효한 학습 백업 파일이 아닙니다.'));}});
window.addEventListener('hashchange',()=>{if(!loaded)return;stopTTS();stopTimer(false);const r=parseRoute();if(r.page==='lesson'&&r.id!==state.recent)touchLesson(r.id);route=r;render();window.scrollTo({top:0,behavior:'instant'})});
document.addEventListener('keydown',ev=>{if(!loaded||route.page!=='lesson'||ev.ctrlKey||ev.altKey||ev.metaKey||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(ev.key==='Escape'){stopTTS();return}if(ev.key===' '){ev.preventDefault();togglePauseTTS()}else if(ev.key.toLowerCase()==='t'){state.settings.translation=!state.settings.translation;save();updateView()}else if(ev.key.toLowerCase()==='s'){speakOne(route.mode==='sentences'?'sentence':'chunk',focusIndex)}else if(focus&&ev.key==='ArrowRight'){focusIndex=Math.min(focusIndex+1,route.mode==='sentences'?getLesson(route.id).sentences.length-1:getLesson(route.id).chunks.flatMap(x=>x.rows).length-1);updateView()}else if(focus&&ev.key==='ArrowLeft'){focusIndex=Math.max(focusIndex-1,0);updateView()}});
applySettings();if(readAuth())loadData();else renderLogin();
})();
